from pathlib import Path
import os, shutil
parent = Path(r'C:\Users\sushm\Downloads\GCP extension\backend\data').resolve(strict=True)
targets = [Path(r'C:\Users\sushm\Downloads\GCP extension\backend\data\source'), Path(r'C:\Users\sushm\Downloads\GCP extension\backend\data\chroma')]
resolved = []
for original in targets:
    if original.is_symlink():
        raise RuntimeError(f'Refusing symlink target: {original}')
    target = original.resolve(strict=True)
    if target.parent != parent:
        raise RuntimeError(f'Refusing target with unexpected direct parent: {target}')
    if not target.is_dir():
        raise RuntimeError(f'Refusing non-directory target: {target}')
    for root, dirs, files in os.walk(target, followlinks=False):
        for name in dirs + files:
            entry = Path(root) / name
            if entry.is_symlink():
                raise RuntimeError(f'Refusing tree containing symlink: {entry}')
    resolved.append(target)
for target in resolved:
    print(f'Contents of {target}:')
    for root, dirs, files in os.walk(target, followlinks=False):
        for name in files:
            print(Path(root, name).relative_to(target))
for target in resolved:
    shutil.rmtree(target)
    print(f'Removed: {target}')
